def solve(a, b):
    """
    Calculate the Levenshtein edit distance between strings a and b.

    :param a: Source string
    :param b: Target string
    :return: Minimum number of single-character edits (insertions, deletions or substitutions) required to change
             string a into string b
    """
    def levenshtein_distance(s, t):
        if s == "":
            return len(t)
        if t == "":
            return len(s)
        if s[-1] == t[-1]:
            cost = 0
        else:
            cost = 1

        res = min([levenshtein_distance(s[:-1], t) + 1,
                   levenshtein_distance(s, t[:-1]) + 1,
                   levenshtein_distance(s[:-1], t[:-1]) + cost])

        return res

    return levenshtein_distance(a, b)
