def parse_duration(s):
    if not s:
        raise ValueError("Input string cannot be empty")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0

    for unit in units:
        value = s.find(unit)
        if value != -1:
            if value == 0 or s[value - 1] not in units:
                raise ValueError(f"Invalid format for unit {unit}")
            if value > 0 and s[value - 1].isdigit():
                num = int(s[:value])
                if num < 0:
                    raise ValueError("Negative numbers are not allowed")
                total_seconds += num * units[unit]
                s = s[value + 1:]
            else:
                raise ValueError(f"Unit {unit} without a number")
        elif unit == 's' and s[-1] not in units:
            raise ValueError(f"Unknown unit at the end of the string: {s[-1]}")

    if any(unit in s for unit in units):
        raise ValueError("Units out of order or repeated units")

    return total_seconds
