def parse_duration(s):
    if not s:
        raise ValueError("Input string cannot be empty")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    seen_units = set()

    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            num = int(s[i:j])

            if s[j] not in units or s[j] in seen_units:
                raise ValueError(f"Invalid unit or repeated unit: {s[j]}")

            seen_units.add(s[j])
            total_seconds += num * units[s[j]]
            i = j + 1
        else:
            raise ValueError(f"Unknown unit: {s[i]}")

    if not seen_units.issubset({'d', 'h', 'm', 's'}) or len(seen_units) != len(units):
        raise ValueError("Units out of order or unknown units")

    return total_seconds
