def topo_sort(deps):
    in_degree = {task: 0 for tasks in deps.values() for task in tasks}
    for task, dependencies in deps.items():
        for dep in dependencies:
            in_degree[dep] += 1

    ready, sorted_tasks = sorted([(task, in_degree[task]) for task in in_degree if in_degree[task] == 0]), []

    while ready:
        task, _ = ready.pop(0)
        sorted_tasks.append(task)

        for dep in deps.get(task, []):
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                ready.append((dep, in_degree[dep]))
                ready = sorted(ready, key=lambda x: (-x[1], x[0]))

    if len(sorted_tasks) != len(deps):
        raise ValueError("Cycle detected in dependencies")

    return sorted_tasks
