    Finds the shortest path from start to goal in a directed graph with non-negative weights.

    :param graph: A dictionary mapping each node to a list of (neighbor, weight) pairs.
    :param start: The starting node.
    :param goal: The goal node.
    :return: A tuple (distance, path) where distance is the cost of the shortest path and path is a list of nodes from start to goal. 
             Returns (None, []) if the goal is unreachable, and (0, [start]) when start == goal.
    """
    if start == goal:
        return (0, [start])

    from heapq import heappop, heappush
    import sys

    # Priority queue storing (distance, node, path)
    queue = [(0, start, [start])]
    visited = set()

    while queue:
        distance, node, path = heappop(queue)
        if node in visited:
            continue
        visited.add(node)

        if node == goal:
            return (distance, path)

        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                new_distance = distance + weight
                new_path = path + [neighbor]
                heappush(queue, (new_distance, neighbor, new_path))

    return (None, [])
