        d, node = heappop(todo)
        if node == goal:
            return (d, path[node])
        if d > dist[node]:
            continue
        for neighbor, weight in graph[node]:
            distance = d + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                path[neighbor] = path[node] + [neighbor]
                heappush(todo, (distance, neighbor))

    return (None, [])
